-- Import the 2026-08-07 Wizards Store Locator snapshot as Leads for Arcane Fortress.
-- The source workbook is intentionally embedded so deployments do not depend on local files.
-- Source totals: 12,692 stores; 685 premium; 7,647 public emails; 12,690 phones; 12,103 websites.

DO $migration_guard$
DECLARE
    organization_count INTEGER;
    target_organization_id TEXT;
BEGIN
    SELECT COUNT(*), MIN("id")
    INTO organization_count, target_organization_id
    FROM "Organization"
    WHERE "name" = 'Arcane Fortress';

    IF organization_count > 1 THEN
        RAISE EXCEPTION 'Wizards store Lead import expected one organization named Arcane Fortress, found %', organization_count;
    END IF;

    IF organization_count = 1 AND NOT EXISTS (
        SELECT 1
        FROM "OrganizationMembership" membership
        INNER JOIN "users" app_user ON app_user."id" = membership."userId"
        WHERE membership."organizationId" = target_organization_id
          AND membership."status" = 'ACTIVE'
          AND app_user."status" = 'ACTIVE'
    ) THEN
        RAISE EXCEPTION 'Wizards store Lead import found Arcane Fortress but no active organization member with an active user';
    END IF;
END;
$migration_guard$;

WITH target_organization AS (
    SELECT "id"
    FROM "Organization"
    WHERE "name" = 'Arcane Fortress'
), target_owner AS (
    SELECT
        target_organization."id" AS "organizationId",
        selected_owner."userId"
    FROM target_organization
    INNER JOIN LATERAL (
        SELECT membership."userId"
        FROM "OrganizationMembership" membership
        INNER JOIN "users" app_user ON app_user."id" = membership."userId"
        WHERE membership."organizationId" = target_organization."id"
          AND membership."status" = 'ACTIVE'
          AND app_user."status" = 'ACTIVE'
        ORDER BY
            CASE WHEN membership."role" = 'ADMIN' THEN 0 ELSE 1 END,
            membership."createdAt",
            membership."id"
        LIMIT 1
    ) selected_owner ON TRUE
), source_store AS (
    SELECT *
    FROM jsonb_to_recordset($wizard_store_data$
