$wizard_store_data$::jsonb) AS store_data(
        "storeId" TEXT,
        "storeName" TEXT,
        "premium" BOOLEAN,
        "address" TEXT,
        "country" TEXT,
        "latitude" TEXT,
        "longitude" TEXT,
        "email" TEXT,
        "phone" TEXT,
        "website" TEXT,
        "storePageUrl" TEXT
    )
)
INSERT INTO "Lead" (
    "id",
    "organizationId",
    "status",
    "lastName",
    "company",
    "website",
    "description",
    "ownerId",
    "phone",
    "email",
    "country",
    "street",
    "leadSource",
    "createdById",
    "updatedById",
    "createdAt",
    "updatedAt"
)
SELECT
    'lead-wizards-store-' || source_store."storeId" || '-' || SUBSTRING(MD5(target_owner."organizationId"), 1, 12),
    target_owner."organizationId",
    'New',
    source_store."storeName",
    source_store."storeName",
    source_store."website",
    CONCAT_WS(
        E'\n',
        'Imported from Wizards Store Locator snapshot 2026-08-07.',
        'Store ID: ' || source_store."storeId",
        'Premium Store: ' || CASE WHEN source_store."premium" THEN 'Yes' ELSE 'No' END,
        'Coordinates: ' || source_store."latitude" || ', ' || source_store."longitude",
        'Store Page URL: ' || source_store."storePageUrl"
    ),
    target_owner."userId",
    source_store."phone",
    source_store."email",
    source_store."country",
    source_store."address",
    'Web',
    target_owner."userId",
    target_owner."userId",
    CURRENT_TIMESTAMP,
    CURRENT_TIMESTAMP
FROM source_store
CROSS JOIN target_owner
ON CONFLICT ("id") DO NOTHING;
